import {esc,card} from './visuals.mjs';
import {renderWearable} from './on-site-display.mjs';
import {roster,workerStatus,WORKER_CASES,STAGES} from './safety-model.mjs';
const body=html=>'<div class="card-body">'+html+'</div>';
const button=(label,action,value,disabled=false)=>`<button class="btn small" data-ws="${action}" data-value="${esc(value)}" ${disabled?'disabled':''}>${label}</button>`;
const select=(label,key,value,options)=>`<label class="ws-field">${label}<select aria-label="${label}" data-ws-input="${key}">${options.map(([id,label])=>`<option value="${id}" ${id===value?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
const weatherOptions=[['clear','Clear conditions'],['heat','Hot day'],['rain','Rain'],['fog','Low visibility'],['wind','Strong wind']];
const weatherAdvice={clear:'No weather advisory in this scenario.',heat:'Check on the team and plan shade, water and relief.',rain:'Check slippery surfaces and equipment visibility.',fog:'Review sight lines and detection coverage.',wind:'Check signs, stands and equipment mounting.'};
export function renderWorkerSupport(site){
 const w=site.worker,status=workerStatus(site),weather=weatherOptions.find(([key])=>site.weather[key])?.[0]||'clear';
 const rows=roster(site).map(person=>{const s=workerStatus(site,person),requests=s.requests;return `<tr class="worker-row ${s.tone} ${person.id===w.id?'selected':''}"><th scope="row"><strong>${esc(person.name)}</strong><small>${esc(person.id)}</small></th><td><span class="worker-state ${s.tone}">${esc(s.label)}</span></td><td>${person.bpm} bpm<small>${Math.floor(person.duty)} min continuous</small></td><td><strong>${s.sos?'SOS sent':requests.some(e=>e.key==='rest')?'Break requested':requests.length?'Automatic alert':'None'}</strong><small>${requests.length?requests.every(e=>e.stage===2)?'Support in progress':requests.every(e=>e.stage>=1)?'Supervisor assigned':'Awaiting supervisor':'No open requests'}</small></td><td>${button(person.id===w.id?'Selected':'View watch','worker-select',person.id,person.id===w.id)}</td></tr>`}).join('');
 const responses=status.requests.map(e=>`<div class="worker-response"><div><strong>${esc(e.title)}</strong><small>${esc(e.id)} · ${STAGES[e.stage]} · ${e.acknowledged?'Worker acknowledged':'Awaiting worker acknowledgement'}</small></div>${e.stage===0?button('Assign supervisor','take',e.id):e.stage===1?button('Arrange support','progress',e.id):'<span class="worker-state attention">Support in progress</span>'}</div>`).join('');
 return `<div class="worker-demo-grid">${card('Worker status','Simulated Apple Watch · select a worker and a scenario',body(`<div class="ws-form">${select('Worker','worker-select',w.id,roster(site).map(p=>[p.id,p.name+' · '+p.id]))}${select('Worker scenario','worker-scenario',w.scenario||'normal',Object.entries(WORKER_CASES))}</div>${renderWearable(site,true)}<p class="note">Readings and reminders are simulated. Changing a scenario does not close an existing request.</p>`))}${card('Weather demo','One scenario for the selected site',body(`${select('Weather scenario','weather-scenario',weather,weatherOptions)}<div class="worker-weather-summary"><span class="ws-eyebrow">${weather==='clear'?'CURRENT SCENARIO':'WEATHER ADVISORY'}</span><h3>${weatherOptions.find(([key])=>key===weather)[1]}</h3><p>${weatherAdvice[weather]}</p></div><p class="note">Simulated weather. Hot conditions can also create a support reminder for workers on extended duty.</p><div class="worker-demo-help"><h3>Try a worker scenario</h3><p><strong>High heart rate</strong> shows an elevated reading on the watch and flags the worker for a check-in.</p><p><strong>Extended continuous work</strong> shows a break reminder.</p><p><strong>SOS / urgent help</strong> turns that worker’s row red. You can also press SOS on the watch.</p><p class="note">These are demonstration triggers, not medical assessments or approved rest intervals.</p></div>`))}</div><div class="section-gap">${card('Workers on site',`${site.name} · ${roster(site).length} simulated workers`,body(`<p class="worker-legend"><span class="worker-state urgent">Red · SOS</span><span class="worker-state attention">Amber · needs support</span><span class="worker-state normal">On duty / support completed</span></p><div class="worker-table-scroll"><table class="worker-table"><thead><tr><th>Worker</th><th>Current status</th><th>Watch readings</th><th>Help / response</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div><section class="worker-response-panel" aria-label="Selected worker support"><h3>Support for ${esc(w.name)}</h3>${responses||'<p>No open support requests for this worker.</p>'}${status.requests.length?`<div class="actions section-gap">${button('Complete support / handover','complete-support','',status.requests.some(e=>e.stage!==2))}</div><p class="note">Assign the requests, arrange support, then record completion. Only this worker’s requests and continuous-duty counter are updated.</p>`:''}${w.breaks.length?'<p class="note">Completed support / breaks recorded: '+w.breaks.length+'</p>':''}</section>`))}</div>`;
}
